/**
 * codemods/replace-with-i18n-ast-i18next.js
 * jscodeshift transform for React + react-i18next
 *
 * Usage (dry-run):
 * npx jscodeshift -t codemods/replace-with-i18n-ast-i18next.js src/pages/saas/SaaSSuppliersPage.tsx \
 *   --extensions=ts,tsx --parser=tsx -d -p -- -replacements=i18n-replacements.json
 *
 * Production run:
 * npx jscodeshift -t codemods/replace-with-i18n-ast-i18next.js src --extensions=ts,tsx --parser=tsx -- -replacements=i18n-replacements.json
 *
 * Behavior:
 *  - Reads i18n-replacements.json (generated by extract script).
 *  - Replaces string literals / template-literals / JSXText that exactly match 'original'.
 *  - For template cases with params, it replaces with t('key', { param })
 *  - Adds `import { useTranslation } from 'react-i18next'` if missing and injects `const { t } = useTranslation();`
 *    at top of function component body (first statement) if needed.
 *  - Skips import specifiers, object keys, member expression properties, tagged templates, require(), and imports.
 */

const fs = require('fs');
const path = require('path');

module.exports = function(fileInfo, api) {
  const j = api.jscodeshift;
  const root = j(fileInfo.source);
  const opts = api.options || {};
  const getOpt = name => opts[name] ?? (process.argv.find(a => a.startsWith(`-${name}=`)) || '').split('=')[1] ?? (process.argv.find(a => a.startsWith(`${name}=`)) || '').split('=')[1];
  const replPath = getOpt('replacements') || './i18n-replacements.json';
  let replacements = [];
  try {
    replacements = JSON.parse(fs.readFileSync(path.resolve(process.cwd(), replPath), 'utf8'));
  } catch (e) {
    return fileInfo.source;
  }
  const map = new Map(replacements.map(r => [r.original, r]));
  if (map.size === 0) return fileInfo.source;

  let applied = 0;

  function buildTCall(key, params) {
    if (!params || params.length === 0) {
      return j.callExpression(j.identifier('t'), [j.literal(key)]);
    }
    const props = params.map(p => j.property('init', j.identifier(p), j.identifier(p)));
    const obj = j.objectExpression(props);
    return j.callExpression(j.identifier('t'), [j.literal(key), obj]);
  }

  function ensureUseTranslationImport() {
    const has = root.find(j.ImportDeclaration, { source: { value: 'react-i18next' }})
      .filter(p => p.node.specifiers.some(s => s.imported && s.imported.name === 'useTranslation')).size() > 0;
    if (!has) {
      const importDecl = j.importDeclaration([j.importSpecifier(j.identifier('useTranslation'))], j.literal('react-i18next'));
      const program = root.get().node.program;
      program.body.unshift(importDecl);
    }
  }

  function ensureTInFunction(funcPath) {
    const body = funcPath.get('body', 'body');
    if (!body || !Array.isArray(body.value)) return;
    const hasT = j(funcPath).find(j.VariableDeclarator, {
      id: { type: 'ObjectPattern', properties: [{ key: { name: 't' } }] }
    }).size() > 0;
    if (hasT) return;

    const call = j.variableDeclaration('const', [
      j.variableDeclarator(
        j.objectPattern([j.property('init', j.identifier('t'), j.identifier('t'))]),
        j.callExpression(j.identifier('useTranslation'), [])
      )
    ]);
    body.value.unshift(call);
  }

  root.find(j.JSXText).forEach(p => {
    const raw = p.node.value;
    if (!raw) return;
    const trimmed = raw.replace(/\s+/g, ' ').trim();
    if (!trimmed) return;
    if (!map.has(trimmed)) return;
    const { key, params } = map.get(trimmed);
    ensureUseTranslationImport();
    const funcAncestor = j(p).closest(j.FunctionDeclaration).paths()[0] || j(p).closest(j.VariableDeclarator).paths()[0];
    if (funcAncestor) ensureTInFunction(funcAncestor);
    const call = buildTCall(key, params);
    j(p).replaceWith(j.jsxExpressionContainer(call));
    applied++;
  });

  root.find(j.JSXAttribute).forEach(p => {
    const val = p.node.value;
    if (!val) return;
    let raw = null;
    if (val.type === 'Literal' && typeof val.value === 'string') raw = val.value;
    else if (val.type === 'JSXExpressionContainer' && val.expression.type === 'Literal' && typeof val.expression.value === 'string') raw = val.expression.value;
    else if (val.type === 'JSXExpressionContainer' && val.expression.type === 'TemplateLiteral' && val.expression.expressions.length === 0) raw = val.expression.quasis[0].value.cooked;
    if (!raw) return;
    let entry = map.get(raw);
    if (!entry) {
      for (const [orig, r] of map.entries()) {
        const normOrig = orig.replace(/\$\{([^}]+)\}/g, '{{$1}}');
        if (normOrig === raw || orig === raw) {
          entry = r; break;
        }
      }
    }
    if (!entry) return;
    const { key, params: entryParams } = entry;
    ensureUseTranslationImport();
    const funcAncestor = j(p).closest(j.FunctionDeclaration).paths()[0] || j(p).closest(j.VariableDeclarator).paths()[0];
    if (funcAncestor) ensureTInFunction(funcAncestor);
    const call = buildTCall(key, entryParams || []);
    p.node.value = j.jsxExpressionContainer(call);
    applied++;
  });

  function unsafeParent(p) {
    if (!p || !p.parent) return false;
    const parent = p.parent.node;
    if (!parent) return false;
    const tpe = parent.type;
    if (tpe === 'ImportDeclaration' || tpe === 'ExportNamedDeclaration' || tpe === 'ExportAllDeclaration') return true;
    if (tpe === 'Property' && p.name === 'key') return true;
    if (tpe === 'MemberExpression' && p.name === 'property') return true;
    if (tpe === 'TaggedTemplateExpression') return true;
    if (tpe === 'CallExpression' && parent.callee && parent.callee.name === 'require') return true;
    return false;
  }

  root.find(j.TemplateLiteral).forEach(p => {
    if (p.node.expressions && p.node.expressions.length === 0) {
      const raw = p.node.quasis[0].value.cooked;
      if (!raw) return;
      let entry = map.get(raw);
      if (!entry) {
        for (const [orig, r] of map.entries()) {
          const norm = orig.replace(/\$\{([^}]+)\}/g, '{{$1}}');
          if (norm === raw || orig === raw) { entry = r; break; }
        }
      }
      if (!entry) return;
      if (unsafeParent(p)) return;
      const { key, params } = entry;
      const funcAncestor = j(p).closest(j.FunctionDeclaration).paths()[0] || j(p).closest(j.VariableDeclarator).paths()[0];
      if (funcAncestor) ensureTInFunction(funcAncestor);
      ensureUseTranslationImport();
      j(p).replaceWith(buildTCall(key, params));
      applied++;
    }
  });

  root.find(j.Literal).forEach(p => {
    if (typeof p.node.value !== 'string') return;
    const str = p.node.value;
    if (!map.has(str)) return;
    if (unsafeParent(p)) return;
    const { key, params } = map.get(str);
    const funcAncestor = j(p).closest(j.FunctionDeclaration).paths()[0] || j(p).closest(j.VariableDeclarator).paths()[0];
    if (funcAncestor) ensureTInFunction(funcAncestor);
    ensureUseTranslationImport();
    j(p).replaceWith(buildTCall(key, params));
    applied++;
  });

  if (applied > 0) {
    console.log(`${fileInfo.path}: applied ${applied} replacements`);
  }
  return root.toSource({ quote: 'single' });
};